Clase Contador
    Privado Definir valor Como Entero;

    Metodo Constructor()
        Este.valor <- 0;
    FinMetodo

    Publico Metodo Incrementar()
        Este.valor <- Este.valor + 1;
    FinMetodo

    Publico Metodo Valor() Como Entero
        Retornar Este.valor;
    FinMetodo
FinClase

Proceso EjecutarContador
    Definir veces Como Entero;
    Definir i Como Entero;
    Definir contador Como Contador;
    Leer veces;
    contador <- Nuevo Contador();
    Para i <- 1 Hasta veces Con Paso 1 Hacer
        contador.Incrementar();
    FinPara
    Escribir contador.Valor();
FinProceso
